// repro for: beyond-precision-numeric-literals (docs/deep-dives/issues/beyond-precision-numeric-literals.md)
// expect: accepted   (skjs check exits 0 — the unsound acceptance at the pin)
// run: make check-file-in-docker FILE=docs/deep-dives/issues/repros/underflow-zero-truthy.ts BIN=target/host/dev/skjs
// The longhand decimal below is 10^-400, which underflows to +0 as a
// double; the normalizer rewrites it to the lexeme "1e-400", which
// isFalsy (lexeme == "0") classifies TRUTHY. So safe mode sees one falsy
// member ("") and the else branch narrows to "" — while at runtime x
// holds +0 (a number, falsy) and takes the else branch. node: prints
// z = 0, typeof z = number. tsc rejects (its literal type is 0).

function u(x: 0. | ""): void {
  if (x) {
    console.log("truthy branch");
  } else {
    const z: "" = x;
    console.log("else branch; z =", JSON.stringify(z), "typeof z =", typeof z);
  }
}
u(0.);
